#!/usr/bin/env node
/**
 * Apply data/sourced-corrections.json to content/, src/data/dose-superseded.json and
 * src/data/composition.json.
 *
 * content/ is regenerated by ingest, so run this after an ingest and after fix-dose-column.mjs,
 * which rewrites dose-superseded.json. It is idempotent: an edit already in place is skipped, and
 * a target text that is missing or not unique is reported and fails the run, so nothing is applied
 * to a page whose wording has moved.
 *
 *   node scripts/apply-sourced-corrections.mjs            report what would change
 *   node scripts/apply-sourced-corrections.mjs --write    apply it
 */
import fs from 'node:fs';
import path from 'node:path';

const WRITE = process.argv.includes('--write');
const data = JSON.parse(fs.readFileSync(path.join('data', 'sourced-corrections.json'), 'utf8'));
const SUPERSEDED = path.join('src', 'data', 'dose-superseded.json');
const COMPOSITION = path.join('src', 'data', 'composition.json');

let applied = 0;
let already = 0;
const problems = [];
const pages = new Map();
const read = (page) => {
  if (!pages.has(page)) pages.set(page, fs.readFileSync(path.join('content', `${page}.md`), 'utf8'));
  return pages.get(page);
};
const count = (text, s) => text.split(s).length - 1;

for (const e of [...data.doses, ...data.text]) {
  const text = read(e.page);
  const n = count(text, e.find);
  if (n === 1) { pages.set(e.page, text.replace(e.find, () => e.replace)); applied += 1; continue; }
  if (n === 0 && e.replace && text.includes(e.replace)) { already += 1; continue; }
  if (n === 0 && !e.replace) { already += 1; continue; }
  problems.push(`${e.page}: target occurs ${n} times: ${e.find.slice(0, 70)}`);
}

const sup = JSON.parse(fs.readFileSync(SUPERSEDED, 'utf8'));
sup.note = 'Dose figures replaced by the figure in the Ayurvedic Formulary of India or the Ayurvedic Pharmacopoeia of India because they carried no source. Kept so the change is reversible and auditable, and listed on /corrections/.';
sup.updatedAt = data.on;
for (const d of data.doses) {
  const [kind, slug] = d.page.split('/');
  const row = { kind, slug, supersededFigure: d.old, replacedWith: d.new, entry: d.source, on: data.on };
  const i = sup.replaced.findIndex((x) => x.kind === kind && x.slug === slug && x.on === data.on && x.supersededFigure === d.old);
  if (i >= 0) sup.replaced[i] = row; else sup.replaced.push(row);
}

const raw = fs.readFileSync(COMPOSITION, 'utf8');
const comp = JSON.parse(raw);
for (const c of data.composition) {
  const rec = comp.records[c.slug];
  if (rec?.[c.field] === c.new) { already += 1; continue; }
  if (rec?.[c.field] !== c.old) { problems.push(`composition ${c.slug}.${c.field} is ${rec?.[c.field]}`); continue; }
  rec[c.field] = c.new;
  applied += 1;
}

console.log(`${WRITE ? 'applied' : 'would apply'} ${applied}, already in place ${already}, problems ${problems.length}`);
for (const p of problems) console.error(`  ${p}`);
if (problems.length) process.exit(1);

if (WRITE) {
  for (const [page, text] of pages) fs.writeFileSync(path.join('content', `${page}.md`), text);
  fs.writeFileSync(SUPERSEDED, `${JSON.stringify(sup, null, 2)}\n`);
  const after = `${JSON.stringify(comp, null, raw.startsWith('{\n  ') ? 2 : 0)}${raw.endsWith('\n') ? '\n' : ''}`;
  fs.writeFileSync(COMPOSITION, after);
}
